"use client";
import { WalletSite } from "./components/wallet-site/site";

export interface ArtemisWalletSiteProps {
  className?: string;
  /** The page to show; changing it switches the page. Links inside the site switch pages on their own. */
  variant?: "home" | "networks" | "security" | "download";
}

/**
 * A four-page marketing site for a mobile wallet. It brings its own stylesheet
 * (`@zeus/ui/artemis-wallet-site.css`, or `styles/artemis/wallet-site.css` from the registry),
 * scoped to its root, and stays light inside a dark host.
 */
export function ArtemisWalletSite({ className, variant = "home" }: ArtemisWalletSiteProps) {
  return <WalletSite className={className} page={variant} />;
}

