"use client";
// @zeus-internal

import { useEffect, useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import { EASE_OUT } from "./ease";
import { CARD_PAYMENT_HTML, CARD_SEND_HTML } from "./markup/cards";

// The card markup stays static; React owns only which of the two cards is present.
function cardContents(snapshot: string) {
  const inner = snapshot.slice(snapshot.indexOf("><") + 1, snapshot.lastIndexOf("</div>")).trim();
  return inner.slice(inner.indexOf(">") + 1, inner.lastIndexOf("</"));
}
// Stable objects, so a re-render never re-applies the same markup.
const sendContents = { __html: cardContents(CARD_SEND_HTML) };
const paymentContents = { __html: cardContents(CARD_PAYMENT_HTML) };

export function PaymentDemo({ reduce }: { reduce: boolean }) {
  const [sent, setSent] = useState(false);
  useEffect(() => {
    if (reduce) return;
    const timer = setInterval(() => setSent((value) => !value), 3400);
    return () => clearInterval(timer);
  }, [reduce]);
  const transition = { duration: reduce ? 0 : 0.22, ease: EASE_OUT };
  return (
    <AnimatePresence initial={false} mode="wait">
      {sent ? (
        <motion.button
          key="payment"
          type="button"
          className="w-full max-w-[19rem] rounded-[1.25rem] bg-paper-raised p-3.5 text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ink"
          initial={reduce ? false : { opacity: 0, transform: "translateY(6px) scale(0.98)" }}
          animate={{ opacity: 1, transform: "translateY(0px) scale(1)" }}
          exit={{ opacity: 0, transform: "translateY(-6px) scale(0.98)" }}
          transition={transition}
          onClick={() => setSent(false)}
          dangerouslySetInnerHTML={paymentContents}
        />
      ) : (
        <motion.div
          key="send"
          className="w-full max-w-[19rem] rounded-[1.25rem] bg-paper-raised p-3.5"
          initial={reduce ? false : { opacity: 0, transform: "translateY(6px)" }}
          animate={{ opacity: 1, transform: "translateY(0px)" }}
          exit={{ opacity: 0, transform: "translateY(-6px)" }}
          transition={transition}
          onClick={(event) => {
            if (event.target instanceof Element && event.target.closest("button")) setSent(true);
          }}
          dangerouslySetInnerHTML={sendContents}
        />
      )}
    </AnimatePresence>
  );
}

"use client";
// @zeus-internal

import { useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import { AnimatePresence, motion } from "motion/react";
import { EASE_OUT } from "./ease";
import { PaymentDemo } from "./payment-demo";

export interface ProductHosts {
  main: HTMLElement;
  reduce: boolean;
  payment: HTMLElement;
  route: { badge: HTMLElement; bar: HTMLElement; eta: HTMLElement; badgeClass: string; barClass: string };
  review: {
    title: HTMLElement;
    badge: HTMLElement;
    badgeClass: string;
    badgeMarkup: string;
    note: HTMLElement;
    noteClass: string;
    noteMarkup: string;
    rows: HTMLElement;
    rowMarkup: Array<{ className: string; html: string }>;
  };
}

function useCycle(start: number, end: number, period: number, reduce: boolean) {
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    if (reduce) return;
    const intervals: Array<ReturnType<typeof setInterval>> = [];
    const schedule = (delay: number, value: boolean) => setTimeout(() => {
      setBusy(value);
      intervals.push(setInterval(() => setBusy(value), period));
    }, delay);
    const on = schedule(start, true);
    const off = schedule(end, false);
    return () => {
      clearTimeout(on);
      clearTimeout(off);
      for (const interval of intervals) clearInterval(interval);
    };
  }, [start, end, period, reduce]);
  return busy;
}

function RouteDemo({ hosts, reduce }: { hosts: ProductHosts["route"]; reduce: boolean }) {
  const busy = useCycle(2600, 3500, 5600, reduce);
  return <>
    {createPortal(<AnimatePresence initial={false} mode="wait">
      <motion.span key={String(busy)} className={hosts.badgeClass}
        initial={reduce ? false : { opacity: 0, transform: "translateY(3px)" }}
        animate={{ opacity: 1, transform: "translateY(0px)" }}
        exit={{ opacity: 0, transform: "translateY(-3px)" }}
        transition={{ duration: reduce ? 0 : 0.18, ease: EASE_OUT }}
      >{busy ? "Routing" : "Best price"}</motion.span>
    </AnimatePresence>, hosts.badge)}
    {createPortal(<motion.span className={hosts.barClass} initial={false}
      animate={{ opacity: busy ? 0.55 : 1, transform: busy ? "scaleX(0.12)" : "scaleX(1)" }}
      transition={{ duration: reduce ? 0 : busy ? 0.18 : 0.65, ease: [0.77, 0, 0.175, 1] }}
    />, hosts.bar)}
    {createPortal(busy ? "Checking" : "~14 sec", hosts.eta)}
  </>;
}

const SCANNING = { __html: '<span class="size-1.5 rounded-full bg-signal"></span>Scanning' };

function ReviewDemo({ hosts, reduce }: { hosts: ProductHosts["review"]; reduce: boolean }) {
  const busy = useCycle(4200, 5300, 5800, reduce);
  const transition = { duration: reduce ? 0 : 0.18, ease: EASE_OUT };
  // Stable objects, so a re-render never re-applies the same markup.
  const ready = useMemo(() => ({ badge: { __html: hosts.badgeMarkup }, note: { __html: hosts.noteMarkup }, rows: hosts.rowMarkup.map((row) => ({ __html: row.html })) }), [hosts]);
  return <>
    {createPortal(busy ? "Simulating changes" : "Simulation complete", hosts.title)}
    {createPortal(<AnimatePresence initial={false} mode="wait">
      <motion.span key={String(busy)} className={hosts.badgeClass}
        initial={reduce ? false : { opacity: 0, transform: "translateY(3px)" }}
        animate={{ opacity: 1, transform: "translateY(0px)" }}
        exit={{ opacity: 0, transform: "translateY(-3px)" }} transition={transition}
        dangerouslySetInnerHTML={busy ? SCANNING : ready.badge}
      />
    </AnimatePresence>, hosts.badge)}
    {createPortal(<>
      {hosts.rowMarkup.map((row, index) => <motion.div key={index} className={row.className} initial={false}
        animate={{ opacity: busy ? 0.38 : 1, transform: busy ? "translateX(-3px)" : "translateX(0px)" }}
        transition={{ duration: reduce ? 0 : 0.2, delay: busy ? 0 : index * 0.06, ease: EASE_OUT }}
        dangerouslySetInnerHTML={ready.rows[index]}
      />)}
    </>, hosts.rows)}
    {createPortal(<AnimatePresence initial={false} mode="wait">
      {busy ? <motion.div key="busy" className={hosts.noteClass}
        initial={reduce ? false : { opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={transition}
      >
        <span className="flex w-3.5 items-center justify-center gap-0.5" aria-hidden="true">
          {[0, 1, 2].map((index) => <motion.span key={index} className="size-0.5 rounded-full bg-positive"
            animate={{ opacity: [0.3, 1, 0.3] }} transition={{ duration: 0.6, delay: index * 0.1, repeat: Infinity, ease: "linear" }}
          />)}
        </span>
        <p className="font-medium text-[8px]">Checking balance and permission changes</p>
      </motion.div> : <motion.div key="ready" className={hosts.noteClass}
        initial={reduce ? false : { opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={transition}
        dangerouslySetInnerHTML={ready.note}
      />}
    </AnimatePresence>, hosts.note)}
  </>;
}

export function ProductDemos({ hosts }: { hosts: ProductHosts }) {
  return <>
    <RouteDemo hosts={hosts.route} reduce={hosts.reduce} />
    {createPortal(<PaymentDemo reduce={hosts.reduce} />, hosts.payment)}
    <ReviewDemo hosts={hosts.review} reduce={hosts.reduce} />
  </>;
}

"use client";
// @zeus-internal
import { useEffect, useId, useLayoutEffect, useRef, useState } from "react";
import { animate, cancelFrame, frame } from "motion/react";
import { EASE_OUT } from "./ease";
import { ProductDemos, type ProductHosts } from "./product-demos";
import { DOWNLOAD_HEADER_HTML, DOWNLOAD_MAIN_HTML } from "./markup/download";
import { FOOTER_HTML, HOME_HEADER_HTML, HOME_MAIN_HTML } from "./markup/home";
import { NETWORKS_HEADER_HTML, NETWORKS_MAIN_HTML } from "./markup/networks";
import { SECURITY_HEADER_HTML, SECURITY_MAIN_HTML } from "./markup/security";

export type WalletSitePage = "home" | "networks" | "security" | "download";

const MAIN: Record<WalletSitePage, string> = { home: HOME_MAIN_HTML, networks: NETWORKS_MAIN_HTML, security: SECURITY_MAIN_HTML, download: DOWNLOAD_MAIN_HTML };
const HEADER: Record<WalletSitePage, string> = { home: HOME_HEADER_HTML, networks: NETWORKS_HEADER_HTML, security: SECURITY_HEADER_HTML, download: DOWNLOAD_HEADER_HTML };
const isPage = (value: string | undefined): value is WalletSitePage => value !== undefined && value in MAIN;
const MENU = "wallet-mobile-navigation";

/** Gives every id in the markup, and every reference to one, this instance's prefix. */
function scoped(html: string, prefix: string) {
  return html
    .replace(/ (id|for|aria-controls|aria-labelledby)="([^"]+)"/g, (_, name: string, value: string) => ` ${name}="${prefix}${value}"`)
    .replace(/url\(#([^)]+)\)/g, (_, id: string) => `url(#${prefix}${id})`);
}

/** The page and fragment an internal link leads to, e.g. `download#ios`. */
const linkKey = (link: HTMLElement) => `${link.dataset.walletPage ?? ""}#${link.dataset.walletHash ?? ""}`;

interface NavigationChange { page: WalletSitePage; hash: string; key: string; region?: "header" | "footer"; footerTop?: number }

/**
 * Keeps the shared shell mounted while page content changes. Pages switch in
 * component state, so the site runs the same in a frame, embedded in a page or
 * as an app route: links never change the URL.
 */
export function WalletSite({ page: requested = "home", className }: { page?: WalletSitePage; className?: string }) {
  const root = useRef<HTMLDivElement>(null);
  const prefix = `wallet${useId().replace(/[^\w-]/g, "")}-`;
  const [initialPage] = useState<WalletSitePage>(() => (isPage(requested) ? requested : "home"));
  const [page, setPage] = useState(initialPage);
  const pageRef = useRef(page);
  pageRef.current = page;
  const renderedPage = useRef(initialPage);
  // One object for the life of the site: React re-applies innerHTML whenever this object changes.
  const [markup] = useState(() => ({ __html: scoped(HEADER[initialPage] + MAIN[initialPage] + FOOTER_HTML, prefix) }));
  const navigation = useRef<NavigationChange | undefined>(undefined);
  const closeMenu = useRef<(() => void) | undefined>(undefined);
  const [productHosts, setProductHosts] = useState<ProductHosts | null>(null);

  // A new `page` prop switches the page, the way a history step did on the original site.
  const requestedRef = useRef(requested);
  useEffect(() => {
    if (requestedRef.current === requested) return;
    requestedRef.current = requested;
    if (!isPage(requested) || requested === pageRef.current) return;
    navigation.current = undefined;
    closeMenu.current?.();
    setPage(requested);
  }, [requested]);

  useLayoutEffect(() => {
    const element = root.current;
    if (!element) return;
    const byId = (id: string) => element.querySelector<HTMLElement>(`[id="${prefix}${id}"]`);
    if (renderedPage.current !== page) {
      const template = document.createElement("template");
      template.innerHTML = scoped(MAIN[page], prefix);
      const main = template.content.firstElementChild;
      if (main) element.querySelector("main")?.replaceWith(main);
      renderedPage.current = page;
    }
    const header = document.createElement("template");
    header.innerHTML = HEADER[page];
    const links = element.querySelectorAll<HTMLAnchorElement>("header a");
    header.content.querySelectorAll<HTMLAnchorElement>("a").forEach((link, index) => {
      if (links[index]) links[index].className = link.className;
    });
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const animations: Array<{ stop: () => void }> = [];
    const setColor = (className: string, property: "color" | "backgroundColor", value: string) => {
      for (const node of element.getElementsByClassName(className)) {
        (node as HTMLElement).style[property] = value;
      }
    };
    setColor("bg-paper-raised/[0.92]", "backgroundColor", "color-mix(in oklab, oklab(1 0 0) 92%, transparent)");
    setColor("bg-paper/18", "backgroundColor", "color-mix(in oklab, oklab(.98 0 0) 18%, transparent)");
    setColor("text-signal-ink/75", "color", "color-mix(in oklab, oklab(1 0 0) 75%, transparent)");
    setColor("text-paper/45", "color", "color-mix(in oklab, oklab(.98 0 0) 45%, transparent)");
    setColor("text-ink/[0.055]", "color", "color-mix(in oklab, oklab(.23 0 0) 5.5%, transparent)");
    setColor("text-paper/48", "color", "color-mix(in oklab, oklab(.98 0 0) 48%, transparent)");
    setColor("bg-paper/10", "backgroundColor", "color-mix(in oklab, oklab(.98 0 0) 10%, transparent)");
    setColor("bg-ink/5", "backgroundColor", "color-mix(in oklab, oklab(.23 0 0) 5%, transparent)");
    const observers: IntersectionObserver[] = [];
    const cleanups: Array<() => void> = [];
    const reveal = (node: HTMLElement, y: number, duration: number, delay = 0, extra: { scale?: number; rotate?: number } = {}) => {
      node.style.opacity = "0";
      node.style.transform = `translateY(${y}px)${extra.scale === undefined ? "" : ` scale(${extra.scale})`}${extra.rotate === undefined ? "" : ` rotate(${extra.rotate}deg)`}`;
      animations.push(animate(node, { opacity: [0, 1], y: [y, 0], ...(extra.scale === undefined ? {} : { scale: [extra.scale, 1] }), ...(extra.rotate === undefined ? {} : { rotate: [extra.rotate, 0] }) }, { duration, delay, ease: EASE_OUT, reduceMotion: reduce }));
    };
    const revealString = (node: HTMLElement, y: number, duration: number, delay = 0) => {
      node.style.opacity = "0";
      node.style.transform = `translateY(${y}px)`;
      animations.push(animate(node, { opacity: [0, 1], transform: [`translateY(${y}px)`, "translateY(0px)"] }, { duration, delay, ease: EASE_OUT }));
    };
    const observeOnce = (node: HTMLElement, enter: () => void, amount = 0.25) => {
      const observer = new IntersectionObserver((entries) => {
        if (!entries.some((entry) => entry.isIntersecting && entry.intersectionRatio >= amount)) return;
        observer.disconnect();
        enter();
      }, { threshold: amount });
      observers.push(observer);
      observer.observe(node);
    };
    if (page === "home" && !reduce) {
      const hero = element.querySelector("main section:first-child");
      const staged = [...(hero?.querySelectorAll<HTMLElement>("[style*='opacity']") ?? [])].filter((node) => node.tagName !== "path");
      const offsets = [16, 20, 16, 16, 16, 42];
      const delays = [0.02, 0.08, 0.16, 0.24, 0.3, 0.28];
      staged.forEach((node, index) => {
        if (index < 6) reveal(node, offsets[index] ?? 16, index === 5 ? 0.9 : 0.62, delays[index], index === 5 ? { scale: 0.975 } : {});
        else reveal(node, 10, 0.45, 0.58 + (index - 6) * 0.07);
      });
      const chartPath = hero?.querySelector<SVGPathElement>("path[style*='opacity']");
      if (chartPath) animations.push(animate(chartPath, { opacity: [0, 1] }, { duration: 0.7, delay: 0.55, ease: "easeOut" }));
    }
    if (page === "home") {
      const product = byId("product");
      const heading = product?.querySelector<HTMLElement>("[style*='opacity']");
      if (heading) {
        heading.style.opacity = "0";
        heading.style.transform = "translateY(22px)";
        observeOnce(heading, () => reveal(heading, 22, 0.65));
      }
      for (const index of [1, 3]) {
        const card = product?.querySelector<HTMLElement>(`article:nth-child(${index}) > div:first-child > div`);
        if (card) {
          card.style.opacity = "0";
          card.style.transform = "translateY(10px)";
          observeOnce(card, () => reveal(card, 10, 0.45), 0.7);
        }
      }
      const faq = byId("faq");
      const faqIntro = faq?.querySelector<HTMLElement>("[style*='opacity']");
      if (faqIntro) {
        faqIntro.style.opacity = "0";
        faqIntro.style.transform = "translateY(18px)";
        observeOnce(faqIntro, () => revealString(faqIntro, 18, 0.55), 0.3);
      }
      const faqs = [...(faq?.querySelectorAll<HTMLElement>("article") ?? [])];
      for (const item of faqs) { item.style.opacity = "0"; item.style.transform = "translateY(16px)"; }
      faqs.forEach((item, index) => observeOnce(item, () => {
        animations.push(animate(item, { opacity: [0, 1], transform: ["translateY(16px)", "translateY(0px)"] }, reduce
          ? { duration: 0 }
          : { type: "spring", stiffness: 330, damping: 30, mass: 0.65, delay: index * 0.055 }));
      }));
      const qr = element.querySelector<HTMLElement>("main > section:last-child [style*='opacity']");
      if (qr) {
        qr.style.opacity = "0";
        qr.style.transform = "translateY(18px)";
        observeOnce(qr, () => revealString(qr, 18, 0.7), 0.35);
      }
    }
    if (page === "download") {
